MATCH (p:Painting)
WHERE EXISTS {
    MATCH (p)-[:displayedAt]->(m:Museum)
    WHERE m.name = 'Pinakothek der Moderne'
  } 
  OR EXISTS {
    MATCH (p)-[:associatedWith]->(a:ArtMovement)
    WHERE a.name = 'analytical cubism' OR 'analytical cubism' IN a.aliases
  }
RETURN DISTINCT p.name AS painting_name

MATCH (p:Painting)-[:associatedWith]->(a:ArtMovement {name: 'Northern Renaissance'})
MATCH (p)-[:hasGenre]->(g:Genre {name: 'battle painting'})
RETURN p.name AS painting_name;

MATCH (s:Sculpture)-[:hasGenre]->(g:Genre)
WHERE s.name IN ['Berger des Nuages', 'Blaise Pascal']
RETURN COUNT(DISTINCT g) AS genreCount;
